/**
 * llm-json-repair.ts — LLM 产出的 JSON 常见语法错误修复
 *
 * LLM 经常产出的 JSON 问题：
 *   1. 数组/对象尾随逗号: [a, b,]  {a: 1,}
 *   2. 字符串中含未转义换行符
 *   3. 对象属性名无引号: {name: "x"}
 *   4. 数组元素间缺逗号（最难修——降级重试）
 */
export declare function extractJSON(content: string): string;
/**
 * 修复 LLM 常见 JSON 错误
 */
export declare function repairLlmJson(jsonStr: string): string;
/**
 * 尝试验证并修复，返回是否修复成功
 */
export declare function tryParseRepaired(jsonStr: string): {
    success: true;
    data: unknown;
} | {
    success: false;
    error: string;
};
